NativeSignal grp0_dequeue_icon_input_event(VM& vm, Thread& thread) {
    const uint32_t processor = thread.stack.pop();
    const uint32_t destination = thread.stack.pop();
    const bool dequeued = vm.dequeue_icon_input_event(processor, destination, thread.base);
    const bool trace = debug_trace(DebugTrace::IconInput);
    if (trace && dequeued) {
        const uint32_t kind = vm.memory().read_u32(destination, thread.base);
        if (kind != 0x10000007U) {
            const auto& input = vm.icon_input_processors().at(processor);
            std::cout << "ICON_INPUT processor=" << processor << " window=0x" << std::hex
                      << input.window << " event=0x" << kind << " item=0x"
                      << vm.memory().read_u32(destination + 4U, thread.base)
                      << " value=0x" << vm.memory().read_u32(destination + 8U, thread.base)
                      << std::dec << " thread=" << thread.id;
            const uint32_t item = vm.memory().read_u32(destination + 4U, thread.base);
            const uint32_t group = item >> 16U, icon = item & 0xFFFFU;
            if (group < input.layout.groups.size() && icon < input.layout.groups[group].icons.size()) {
                const auto& record = input.layout.groups[group];
                std::cout << " group_flags=" << record.words[15]
                          << " icon_flags=" << record.icons[icon].words[48]
                          << " repeat_guard=" << record.icons[icon].words[13]
                          << " selected=" << record.words[3];
            }
            std::cout << '\n';
        }
    }
    thread.stack.push(dequeued);
    return NativeSignal::Continue;
}
